def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        return min(budget, 21)

    total_players = 1 + len(alive_opponents)
    scarcity = float(supply) / float(total_players * WATER_REQ)

    prev_bids = []
    desperate_opponents = 0
    rich_opponents = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_opponents += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            desperate_opponents += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0

    if hp <= 2 or no_water_days >= 2:
        base = DAILY_SALARY * 0.92
    elif hp <= 4 or no_water_days >= 1:
        base = DAILY_SALARY * 0.72
    else:
        if scarcity >= 1.2:
            base = DAILY_SALARY * 0.34
        elif scarcity >= 0.9:
            base = DAILY_SALARY * 0.48
        elif scarcity >= 0.7:
            base = DAILY_SALARY * 0.62
        else:
            base = DAILY_SALARY * 0.8

    if desperate_opponents > 0 and hp > 4 and no_water_days == 0:
        base -= 6
    if rich_opponents >= max(1, len(alive_opponents) // 2):
        base += 4

    if highest_prev > 0:
        if hp <= 4 or no_water_days >= 1:
            target = highest_prev + 2
            if target > base:
                base = target
        else:
            if highest_prev >= DAILY_SALARY * 0.85:
                base = min(base, DAILY_SALARY * 0.42)
            else:
                soft_target = highest_prev + 1
                if soft_target > base and scarcity < 1.0:
                    base = soft_target

    if budget < DAILY_SALARY * 0.6 and hp > 3 and no_water_days == 0:
        base = min(base, budget * 0.55)

    if base < 0:
        base = 0
    if base > budget:
        base = budget

    return float(base)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Budget guard
    my_budget = float(my_status['budget'])
    my_hp = float(my_status['hp'])

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if not alive_opponents:
        # If alone, bid enough to secure water without overpaying
        target = min(my_budget, DAILY_SALARY * 0.45)
        return float(target)

    # Read yesterday bids from previous_trace only
    prev_bids = []
    prev_hp = []
    for opp_id, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass
        try:
            prev_hp.append(float(opp.get('hp', 0)))
        except Exception:
            prev_hp.append(0.0)

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else 0.0

    # Estimate how tight the market is today
    # If supply is near MIN_SUPPLY, scarcity likely; bid more to avoid no-water days.
    scarcity_ratio = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY) + 1e-9)
    scarcity_ratio = max(0.0, min(1.0, scarcity_ratio))
    scarcity = 1.0 - scarcity_ratio  # 0..1

    # Determine baseline bid based on our hp
    # If low hp, we must buy water more aggressively.
    if my_hp <= 2.0:
        base = DAILY_SALARY * (0.75 + 0.15 * scarcity)
    elif my_hp <= 4.0:
        base = DAILY_SALARY * (0.60 + 0.15 * scarcity)
    else:
        base = DAILY_SALARY * (0.50 + 0.10 * scarcity)

    # Exploit opponent pressure from yesterday
    # If someone bid very high yesterday, they likely continued; we slightly undercut/contest.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Contest but not fully: aim around 0.82..0.88 of salary depending on our hp
        if my_hp <= 2.0:
            bid = DAILY_SALARY * (0.88 + 0.05 * scarcity)
        elif my_hp <= 4.0:
            bid = DAILY_SALARY * (0.84 + 0.04 * scarcity)
        else:
            bid = DAILY_SALARY * (0.82 + 0.03 * scarcity)
    else:
        # If no extreme bids, we can try to win with a moderate bid.
        # Use highest_prev_bid as a soft anchor to stay competitive.
        anchor = highest_prev_bid
        if anchor > 0.0:
            # Slightly above second-highest to beat if they cluster bids
            bid = max(base, min(my_budget, second_prev_bid + 1.5))
        else:
            bid = base

    # Ensure we don't overspend beyond budget
    bid = min(float(my_budget), float(bid))

    # If supply is enough that we can afford a lower bid, reduce a bit to save budget.
    if scarcity < 0.35 and my_hp > 4.0:
        bid = min(bid, DAILY_SALARY * 0.45)

    # Never bid negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    my_hp = my_status['hp']
    my_budget = my_status['budget']

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if my_hp <= 2:
        return min(my_budget, DAILY_SALARY * 0.9)

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        target_bid = max(DAILY_SALARY * 0.45, max_prev + 1)
        return min(my_budget, target_bid)

    return min(my_budget, DAILY_SALARY * 0.55)
